    TEXTS = Cybertrain::BundledLocales.text_table.freeze
    LISTS = Cybertrain::BundledLocales.list_table.freeze

    def self.lookup(key) = TEXTS[key]

    def self.lookup_list(key) = LISTS.fetch(key, [])

    def self.resolver = ->(key) { Cybertrain::BundledLocales.lookup(key) }

    def self.list_resolver = ->(key) { Cybertrain::BundledLocales.lookup_list(key) }
  end
